     import org.apache.commons.csv.CSVFormat;
     import org.apache.commons.csv.CSVParser;
     import org.apache.commons.csv.CSVRecord;

     import java.io.FileReader;
     import java.util.HashMap;
     import java.util.Map;

     public class GeomagneticData {
         static class GeomagneticDataPoint {
             String location;
             double latitude, longitude, intensity;

             // Constructor, getters, and setters
         }

         public static Map<String, GeomagneticDataPoint> loadAndParseData(String csvFilePath) throws Exception {
             Map<String, GeomagneticDataPoint> dataMap = new HashMap<>();
             try (CSVParser parser = new CSVParser(new FileReader(csvFilePath), CSVFormat.DEFAULT.withHeader())) {
                 for (CSVRecord record : parser) {
                     String location = record.get("Location");
                     double lat = Double.parseDouble(record.get("Latitude"));
                     double lon = Double.parseDouble(record.get("Longitude"));
                     double intensity = Double.parseDouble(record.get("Magnetic Field Intensity (Tesla)")); 
                     dataMap.put(location, new GeomagneticDataPoint(location, lat, lon, intensity));
                 }
             }
             return dataMap;
         }
     }
     ```

