function reorderAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectiveIndices = []; // Track positions of adjectives

  // 1. Identify Adjectives:
  for (let i = 0; i < words.length; i++) {
    if (isAdjective(words[i])) {  // Use a helper function to check (see below)
      adjectiveIndices.push(i);
    }
  }

  // 2. Swap Positions:
  if (adjectiveIndices.length >= 2) {  // Ensure at least two adjectives exist
    const temp = words[adjectiveIndices[0]];
    words[adjectiveIndices[0]] = words[adjectiveIndices[1]];
    words[adjectiveIndices[1]] = temp;
  }

  // 3. Reconstruct Sentence:
  return words.join(' ');
}

// Helper function to identify adjectives (simple approximation, refine as needed)
function isAdjective(word) {
  //  Advanced techniques (NLP models or dictionaries) would improve accuracy here
  return ['beautiful', 'green', 'tall', 'small', 'red', ... /* more adjectives */].includes(word) || 
         word.endsWith('able') || word.endsWith('ful'); 
}

// Example Usage:
