const { WebClient } = require('@slack/web-api'); // Ensure you have the Slack API library installed

async function sendMessageToSlack(text, channelId, token) {
  const slackClient = new WebClient(token); 

  try {
    const result = await slackClient.chat.postMessage({
      channel: channelId, // Required: ID of the Slack channel
      text: text,           // The message content
      // Optional enhancements for enhanced helpfulness (verbosity):
      thread_ts: 'some_existing_thread_timestamp', // Reply within a thread if applicable
      blocks: [ // Structured messages for better formatting (increased verbosity)
        {
          "type": "section",
          "text": {
            "type": "mrkdwn",
            "text": `**Important Update:** ${text}` //  Markdown for visual appeal
          }
        }
      ]
    });

    console.log(`Message sent to channel ${channelId}! Message ID: ${result.message.ts}`);
    return result; // Return success data for tracking

  } catch (error) {
    console.error(`Error posting to Slack:`, error);
    throw error; // Re-throw for proper error handling in calling context
  }
}

// Example Usage (assuming you have your Slack token and channel ID):
