int buttonPin = GPIO0; // Change to your button GPIO pin
unsigned long lastButtonPress = 0; // Track last button press time
const unsigned long debounceDelay = 50; // Debounce time (ms)
int currentLed = 0; // Index of the currently active LED

void setup() {
  Serial.begin(115200);
  pinMode(buttonPin, INPUT_PULLUP); // Internal pull-up resistor for button
  FastLED.setBrightness(100); // Adjust brightness (0-255)
}

void loop() {
  // Button Debouncing
