#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function with error handling
pair<int, int> fibonacci(int prev1, int prev2, int count) {
    if (count <= 0) {
        return make_pair(prev1, prev2); // Base case: return initial values
    } else if (count == 1) {
        return make_pair(prev2, prev1 + prev2); // Single element case
    } else {
        auto nextPair = fibonacci(prev2, prev1 + prev2, count - 1);
        return nextPair;  // Recursively calculate and return the next pair
    }
}

int main() {
    int num1, num2, length;
    cout << "Enter the first two Fibonacci numbers: ";
    while (!(cin >> num1 >> num2)) {  // Input validation for numbers
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        cerr << "Invalid input. Please enter two integers: ";
    }

    cout << "Enter the desired sequence length: ";
    while (!(cin >> length) || length <= 0) {  // Validate length input
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        cerr << "Invalid input. Enter a positive integer for length: ";
    }

    // Generate and output the sequence
    auto seqPair = fibonacci(num1, num2, length);
    cout << "Fibonacci Sequence (";
    cout << seqPair.first << ", " << seqPair.second;
    for (int i = 3; i <= length; ++i) {
        auto next = fibonacci(seqPair.second, seqPair.first + seqPair.second, i - 1);
        cout << ", " << next.second;
        seqPair = next; // Update for next iteration
    }
    cout << ")" << endl;

    return 0;
}
