    {
        _baseUrl = baseUrl;
        _authToken = initialAuthToken;
        _client = new HttpClient { BaseAddress = new Uri(_baseUrl) };
        // Add default headers (e.g., Content-Type) here if needed
    }

    /// <summary>
    /// Sets a new authentication token for subsequent requests.
    /// </summary>
    public void SetAuthToken(string token) => _authToken = token;

    /// <summary>
    /// Makes a GET request to the specified endpoint with automatic auth token handling.
    /// </summary>
    public async Task<T> GetAsync(string endpoint, params KeyValuePair<string, string>[] queryParameters)
    {
        var uriBuilder = new UriBuilder(_baseUrl + endpoint);
        if (queryParameters.Length > 0)
            uriBuilder.Query = System.Web.HttpUtility.ParseQueryString(uriBuilder.Query).Add(queryParameters);

        return await AddHeadersAndExecute<T>(HttpMethod.Get, uriBuilder.Uri);
    }

    /// <summary>
    /// Makes a POST request with JSON payload and auth token handling.
    /// </summary>
    public async Task<T> PostAsync<S>(string endpoint, S data) where S : class
