function determineMostRelevantProtocol(inputData) {
  // **Analysis & Weighted Reasoning:**

  // High weight to IPv6 due to direct presence in input and typical application context
  const ipv6Relevance = inputData.sourceIP && inputData.destinationIP ? 95 : 0; 
  // HTTP strongly indicated by port 80 and textual payload (common web communication)
  const httpRelevance = inputData.port === 80 && typeof inputData.payload === 'string' ? 80 : 0;
  // UDP less likely given structured, reliable data transfer implied by other factors
  const udpRelevance =  inputData.payload && inputData.sourceIP && inputData.destinationIP ? 10 : 0; // Minor relevance as UDP *could* be used, but less probable here

  // Weighted Score Calculation:
  const scores = { IPv6: ipv6Relevance, HTTP: httpRelevance, UDP: udpRelevance };
  let maxProtocol = 'IPv6'; // Initial assumption
  let highestScore = ipv6Relevance;

  for (const protocol in scores) {
    if (scores[protocol] > highestScore) {
      highestScore = scores[protocol];
      maxProtocol = protocol;
    }
  }

  return maxProtocol;
}

