import { Injectable } from '@nestjs/common';
import { CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PrismaService } from '../prisma/prisma.service';
import { User } from '../user/user.entity';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, private prisma: PrismaService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    if (!requiredRoles) return true; 

    const request = context.switchToHttp().getRequest();
    const user = request.user as User;
    const userRoles = await this.prisma.userRole.findMany({ where: { userId: user.id } });
    const grantedRoles = userRoles.map(role => role.roleId).map(id => this.prisma.role.findUnique({ where: { id } }).then(r => r?.name));
    const hasAccess = await Promise.all(grantedRoles).then(roles => roles.some(role => requiredRoles.includes(role)));

    if (!hasAccess) throw new UnauthorizedException('Insufficient permissions');
    return hasAccess;
  }
}

// Example Permission Array (within AppModule or similar for configuration)
export const PERMISSIONS = [
  'READ_DATA', 'CREATE_DATA', 'UPDATE_DATA', 'DELETE_DATA', 'ADMIN_CONTROL', // Customize...
];
``` 

