```typescript
import { Injectable } from '@nestjs/common';
import { CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import { Role } from './entities/user.entity';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, private prisma: PrismaService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<Role[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // No roles restriction

    const request = context.switchToHttp().getRequest();
    const user = request.user;
    if (!user || !user.role) throw new UnauthorizedException('Unauthorized');

    const hasAccess = await this.prisma.userRole.findMany({
      where: { userId: user.id, roleId: { in: requiredRoles } },
    }).then(roles => roles.length > 0);

    return hasAccess;
  }
}

// Example Permission Array (within AppModule or similar for configuration)
export const PERMISSIONS = [
  'READ_DATA', 'CREATE_DATA', 'UPDATE_DATA', 'DELETE_DATA', 'ADMIN_CONTROL',
];
```

