function geocodePlaceNames(spreadsheet, sheetName, placeColumn, latColumn, lngColumn) {
  // 1. Get Spreadsheet and Sheet Objects
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);

  // 2. Fetch Place Names and Process Row by Row
  const lastRow = sheet.getLastRow();
  for (let row = 2; row <= lastRow; row++) {  // Start from row 2 assuming header row is row 1
    const placeName = sheet.getRange(row, placeColumn).getValue();
    if (placeName) {  // Only proceed if there's a place name
      // 3. Geocoding using Places API (Requires API Key Setup)
      const geocoder = new google.maps.Geocoder();
      const request = { address: placeName };
      geocoder.geocode(request, (results, status) => {
        if (status === google.maps.GeocoderStatus.OK) {
          const latitude = results[0].geometry.location.lat();
          const longitude = results[0].geometry.location.lng();

          // 4. Store Lat/Long in Spreadsheet
          sheet.getRange(row, latColumn).setValue(latitude);
          sheet.getRange(row, lngColumn).setValue(longitude);
          Logger.log(`Successfully geocoded "${placeName}" - Lat: ${latitude}, Lng: ${longitude}`); 
        } else {
          Logger.log(`Error geocoding "${placeName}": ${status}`);
          // Handle geocoding errors (e.g., set an error marker in spreadsheet)
        }
      });
    }
  }
}
