<?php

function smart_sort_array(array $set, string $order = 'asc'): array {
    /**
     * Sorts an array of associative sub-arrays based on the 'age' key in ascending or descending order.
     *
     * @param array $set Array of sub-arrays, each with 'name', 'address', and 'age' keys.
     * @param string $order Sorting order ('asc' for ascending, 'desc' for descending, default: 'asc').
     * @return array Sorted array.
     */
    usort($set, function($a, $b) use ($order) {
        $comparison = $order === 'asc' ? 1 : -1; // Determine comparison direction
        return $comparison * ($a['age'] - $b['age']); 
    });
    return $set;
}

// Example Usage:
$people = [
    ['name' => 'Alice', 'address' => 'NY', 'age' => 25],
    ['name' => 'Bob', 'address' => 'CA', 'age' => 30],
    ['name' => 'Charlie', 'address' => 'TX', 'age' => 20]
];

// Sort in ascending order (default)
$sortedAsc = smart_sort_array($people);
print_r($sortedAsc); 

// Sort in descending order
$sortedDesc = smart_sort_array($people, 'desc');
print_r($sortedDesc); 
