function extractNestedValuesByDotNotation(options, keyString) {
  const keys = keyString.split('.'); // Break down the dot-notated key into individual parts
  let currentLevel = options;

  // Traverse the nested object structure
  for (const key of keys) {
    if (typeof currentLevel === 'object' && currentLevel !== null && key in currentLevel) {
      currentLevel = currentLevel[key]; // Move to the next nested level
    } else {
      return undefined; // Key not found, return undefined
    }
  }

  // Return the final value (all nested levels traversed successfully)
  return currentLevel; 
}
