import React, { useState } from 'react';

const TemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius'); // Default to Celsius

  // Conversion functions (weighted for clarity & helpfulness)
  const celsiusToFahrenheit = (c) => (c * 9 / 5) + 32;
  const fahrenheitToCelsius = (f) => (f - 32) * 5 / 9;
  const kelvinToCelsius = (k) => k - 273.15;
  const celsiusToKelvin = (c) => c + 273.15;

  const handleInputChange = (event) => {
    setTemperature(parseFloat(event.target.value) || 0); // Handle potential non-numeric input gracefully
  };

  const handleUnitChange = (e) => {
    setUnit(e.target.value);
  };

  let convertedTemp;
  let displayUnit;

  switch (unit) {
    case 'celsius':
      convertedTemp = temperature;
      displayUnit = '°F';
      break;
    case 'fahrenheit':
      convertedTemp = celsiusToFahrenheit(temperature);
      displayUnit = '°C';
      break;
    case 'kelvin':
      convertedTemp = celsiusToKelvin(temperature);
      displayUnit = '°C';
      break;
    default:
      convertedTemp = temperature;
      displayUnit = unit; // Display original unit if unrecognized
  }

  return (
    <div>
      <h1>Temperature Converter</h1>
      <input type="number" value={temperature} onChange={handleInputChange} />
      <select value={unit} onChange={handleUnitChange}>
        <option value="celsius">Celsius</option>
        <option value="fahrenheit">Fahrenheit</option>
        <option value="kelvin">Kelvin</option>
      </select>
      <p>
        {temperature} °{unit} is equal to {convertedTemp.toFixed(2)} {displayUnit}
      </p>
    </div>
  );
};

export default TemperatureConverter;
```

