import React, { useState } from 'react';

const TemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0); // Initial temperature value
  const [unit, setUnit] = useState('celsius'); // Default unit: Celsius

  // Conversion functions (weighted for clarity & usefulness)
  const celsiusToFahrenheit = (celsius) => (celsius * 9/5) + 32;
  const fahrenheitToCelsius = (fahrenheit) => (fahrenheit - 32) * 5/9;

  const handleInputChange = (event) => {
    setTemperature(parseFloat(event.target.value)); // Handle numeric input
  };

  const handleUnitChange = (event) => {
    setUnit(event.target.value);
  };

  let convertedTemp;
  let displayUnit;

  if (unit === 'celsius') {
    convertedTemp = celsiusToFahrenheit(temperature);
    displayUnit = '°F';
  } else {
    convertedTemp = fahrenheitToCelsius(temperature);
    displayUnit = '°C';
  }

  return (
    <div>
      <h1>Temperature Converter</h1>
      <input 
        type="number" 
        value={temperature} 
        onChange={handleInputChange} 
        placeholder="Enter temperature" 
      />
      <select value={unit} onChange={handleUnitChange}>
        <option value="celsius">Celsius</option>
        <option value="fahrenheit">Fahrenheit</option>
      </select>
      <p><b>{temperature}°{unit}</b> is equivalent to <b>{convertedTemp.toFixed(2)}{displayUnit}</b></p>
    </div>
  );
};

export default TemperatureConverter;
```

