// extractStructSchema extracts Avro schema definition from a given Go struct AST node.
func extractStructSchema(structNode *ast.StructType, packageName string) (*schema.Schema, error) {
	fields := make([]*schema.Field, 0)
	for _, field := range structNode.Fields.List {
		fieldName := field.Names[0].Name
		fieldTyp := field.Type

		// Handle basic types and arrays/slices (simple conversion)
		var avroType string
		switch t := fieldTyp.(type) {
		case *ast.Ident:
			// Primitive types (string, int, bool, etc.)
			switch t.Name {
			case "string":
				avroType = "string"
			case "int", "int8", "int16", "int32", "int64":
				avroType = "int"
			case "uint", "uint8", "uint16", "uint32", "uint64":
				avroType = "long" // Avro uses long for unsigned ints
			case "float32", "float64":
				avroType = "double"
			case "bool":
				avroType = "boolean"
			default:
				return nil, fmt.Errorf("unsupported primitive type: %s", t.Name)
			}
		case *ast.ArrayType:
			elemType := extractSchema(t.Elt, packageName)
			avroType = fmt.Sprintf("array<%s>", elemType.String())
		default:
			// Recursively handle nested structs/interfaces (more complex)
			nestedSchema, err := extractSchema(fieldTyp, packageName)
			if err != nil {
				return nil, err
			}
			avroType = nestedSchema.String()
		}

		fields = append(fields, &schema.Field{
			Name:       fieldName,
			Type:       avroType,
			Doc:        "",

