    FROM orders
    WHERE product_name = '$targetProduct'
    GROUP BY customer_id
    HAVING COUNT(DISTINCT purchase_date) >= 3 
    AND DATE_SUB(CURDATE(), INTERVAL 7 DAY) <= purchase_date  -- Filter within the last week
";

// 4. Execute Query and Fetch Results
$result = mysqli_query($conn, $sql);

// 5. Process and Present Loyal Customer Roster (Verbose Output)
echo "<h2>Loyal Customers for '$targetProduct' (Past Week):</h2>";
if (mysqli_num_rows($result) > 0) {
    while($row = mysqli_fetch_assoc($result)) {
        $customerID = $row['customer_id'];
        echo "<p>Customer ID: $customerID  (Purchased '$targetProduct' at least 3 times this week)</p>";
    }
} else {
    echo "<p>No customers meet the criteria for frequent purchases of '$targetProduct' this week.</p>";
}

// 6. Closure (Important for Resource Management)
mysqli_close($conn);

?>
```

