using System;
using System.Collections.Generic;

public class HaikuComposer
{
    private static readonly List<string> NatureWords = new() { "misty", "emerald", "whispers", "solitude", "ancient", "reaching", "sentinel" }; // Thematic words
    private static readonly List<string> SyllableCounts = new() { "5,7,5" }; //  Haiku structure

    public string ComposeHaiku(string FocusWord = "tree")
    {
        Random rand = new Random();
        string haiku = "";

        // Line 1 (5 syllables)
        haiku += NatureWords[rand.Next(NatureWords.Count)] + " meadow, " + FocusWord + " stands "; 

        // Line 2 (7 syllables)
        haiku +=  GetExtendedPhrase(rand, SyllableCounts[0].Split(',')[1]) + " boughs, " + FocusWord + "'s silhouette";

        // Line 3 (5 syllables)
        haiku += ", a " + NatureWords[rand.Next(NatureWords.Count)] + "  grace";

        return haiku;
    }

    private string GetExtendedPhrase(Random rand, int targetSyllables)
    {
        string phrase = "";
        int syllableCount = 0;
        while (syllableCount < targetSyllables)
        {
            phrase += NatureWords[rand.Next(NatureWords.Count)] + " ";
            syllableCount++; // Approximate syllable count (simple heuristic)
        }
        return phrase.Trim(); 
    }
}

