import React, { useState, useEffect } from 'react';
import { Combobox, Input, Listbox, Transition } from 'downshift';
import { searchEmails } from './emailService'; // Assuming your async function resides here

const EmailAutocomplete = () => {
  const [emails, setEmails] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState('');

  const handleInputChange = (newValue: string) => {
    setInputValue(newValue);
    // Trigger email search on input change with debounce for performance
    const debouncedSearch = setTimeout(() => {
      searchEmails(newValue).then(results => setEmails(results));
    }, 300); // Adjust debounce delay as needed
    return () => clearTimeout(debouncedSearch); // Cleanup for debounce
  };

  return (
    <Combobox
      defaultIndex={0} // Optional: Initial focus
      onChange={(selectedItem) => {
        // Handle selection, e.g., set form value or trigger action
        setInputValue(selectedItem || ''); 
      }}
      itemToString={(item) => item} // String representation for display
    >
      <div className="email-autocomplete">
        <Input
          value={inputValue}
          onChange={handleInputChange}
          placeholder="Enter email address..."
          className="input-field"
        />
        <Transition show={emails.length > 0}>
          {(style) => (
            <Listbox
              {...style}
              className="dropdown-list"
              items={emails}
              renderLabel={(item) => item} // Display email addresses
            />
          )}
        </Transition>
      </div>
    </Combobox>
  );
};

export default EmailAutocomplete;
```

