        var vocabulary = vectorizer.BuildVocabulary(dataset.Select(x => x.Sentence).ToArray());
        var featureMatrix = vectorizer.Transform(dataset.Select(x => x.Sentence).ToArray());

        // 3. **Naive Bayes Model Training**
