using Accord.MachineLearning;
using Accord.MachineLearning.Bayes;
using Accord.NLP;
using System;
using System.Collections.Generic;

public class NaiveBayesTextClassifier
{
    public static void Main(string[] args)
    {
        // 1. Prepare Dataset (Simulated for brevity)
        var dataset = new List<Tuple<string, string>>
        {
            // Example data points (Sports, Politics, Entertainment)
            Tuple.Create("The basketball match was thrilling", "Sports"),
            Tuple.Create("Congress debated a crucial bill", "Politics"),
            Tuple.Create("New movie release garnered rave reviews", "Entertainment"),
            // ... populate with your complete labeled dataset ...
        };

        // 2. Feature Extraction (Word Counts using CountVectorizer)
        var vectorizer = new CountVectorizer();
        var featureMatrix = vectorizer.Transform(dataset.Select(x => x.Item1).ToArray());

        // 3. Label Encoding (Mapping categories to numerical labels)
        var labels = dataset.Select(x => x.Item2).ToArray();
        var encoder = new OneHotEncoder();
        var encodedLabels = encoder.FitTransform(labels);

        // 4. Naive Bayes Model Training
        var naiveBayes = new NaiveBayes<double>(encodedLabels.Length); // Adjust length based on categories
        naiveBayes.Train(featureMatrix, encodedLabels);

        // 5. Conditional Probability Calculation (Implicit in trained model)
        //   -  Naive Bayes internally computes P(word|category) probabilities.

        // 6. Prediction on New Sentence
        string newSentence = "The sports game was exciting";
        var newFeatureVector = vectorizer.Transform(new string[] { newSentence });
        var predictedLabelIndex = naiveBayes.Decide(newFeatureVector);
        string predictedCategory = encoder.InverseTransform(predictedLabelIndex)[0]; // Map back to category

        Console.WriteLine($"Prediction for '{newSentence}': {predictedCategory}");
    }
}
```

