import Foundation

func optimisticGratitudeRearrangement(_ phrase: String) -> String {
    // 1. Extract & Prioritize Positive Vibes:  Identify and preferentially place common optimistic/gratitude-linked letters/patterns (e.g., "love", "joy", "thank",  initial vowels like "a", "i", "o" at beginnings for a brighter tone) using a custom priority dictionary. This adds a semantic layer beyond simple sorting.
    let positivityPrioritization = ["love": 5, "joy": 4, "thank": 3, "a": 2, "i": 2, "o": 2] // Example priorities, customizable
    var prioritizedChars = [Character]()
    var remainingChars = Array(phrase.filter { !$0.isWhitespace })

    for (word, priority) in positivityPrioritization {
        for char in word.uppercased() {
            if remainingChars.contains(char) {
                prioritizedChars.append(char)
                remainingChars.removeAll(where: { $0 == char }) // Ensure not duplicated
            }
        }
    }
    prioritizedChars.append(contentsOf: remainingChars.sorted()) // Add remaining in sorted order

    // 2. Construct with Gratitude Emphasis:
    let structuredPhrase = String(prioritizedChars)
    return "Embrace the good with \(structuredPhrase)! Cultivating gratitude and optimism in every moment."

}

