import Foundation

func optimisticallyRearrangePhrase(_ phrase: String) -> String {
    // 1. Extract & Prioritize Positive Vibes:
    let positiveKeywords = ["joy", "hope", "grate", "love", "bless", "thank", "good", "bright"].compactMap { keyword in
        phrase.lowercased().contains(keyword) ? keyword : nil
    }
    let prioritizedLetters = String(positiveKeywords.joined().flatMap { $0.unicodeScalars }).unicodeScalars.sorted()

    // 2.  Structured Rearrangement with Gratitude Emphasis:
    let remainingLetters = phrase.filter { !$0.isWhitespace && !positiveKeywords.joined().contains($0.lowercased()) }.sorted()
    let rearranged = String(prioritizedLetters) + String(remainingLetters)

    // 3.  Craft the Optimistic Output:
    return "Embrace the good with \(rearranged)! Cultivate gratitude and \(phrase.capitalized), remembering life's beauty shines brightly."
}

