const redis = require('redis');

class RedisClient {
  constructor(host = 'localhost', port = 6379) {
    this.client = redis.createClient({ host, port });

    // Error handling with console logging
    this.client.on('error', (err) => console.error(`Redis Client Error: ${err}`));
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true; // Connection successful
    } catch (error) {
      console.error('Redis Connection Check Failed:', error);
      return false; // Connection issue
    }
  }

  async get(key) {
    try {
      return await this.client.get(key);
    } catch (error) {
      console.error(`Error retrieving value for key "${key}":`, error);
      throw error; // Re-throw for higher-level handling
    }
  }

  async set(key, value, duration) {
    try {
      await this.client.set(key, value, 'EX', duration); // Set with expiration
      console.log(`Value set for key "${key}" expiring in ${duration} seconds`);
    } catch (error) {
      console.error(`Error setting key "${key}":`, error);
      throw error;
    }
  }

  async del(key) {
    try {
      const result = await this.client.del(key);
      if (result === 1) {
        console.log(`Key "${key}" successfully deleted`);
      } else {
        console.warn(`Key "${key}" not found or deletion failed`);
      }
    } catch (error) {
      console.error(`Error deleting key "${key}":`, error);
      throw error;
    }
  }
}

// Export an instance for use
const redisClient = new RedisClient();
module.exports = redisClient;
```

