    // ... your initial array data ...
    ],
    isLoadingMNP: true // Track API loading state for each item
  };

  checkMNPStatusAPI = async (phoneNo, index) => {
    const { registrations } = this.state; // Access state directly

    try {
      const headers = new Headers();
      headers.append("Authorization", "Bearer " + user.getAccessToken());
      const response = await fetch(api.checkPortInStatus(user.getProductCode(), phoneNo), {
        headers: headers,
        method: 'GET'
      });
      const rjson = await response.json();

      // Update state *efficiently* using spread syntax and indexing
      this.setState((prevState) => ({
        registrations: prevState.registrations.map((reg, i) => 
          i === index ? { ...reg, mnpStatus: rjson.status } : reg 
        ),
        isLoadingMNP: false // Mark loading as done for this item
      })); 
    } catch (error) {
      console.error("MNP Status API Error:", error);
      // Handle errors gracefully (e.g., display a message)
    }
  };

  // Lifecycle or triggered update (useEffect for fetching on mount/changes)
  useEffect(() => {
    const fetchDataAndUpdate = async () => {
      registrations.forEach((reg, index) => {
        this.checkMNPStatusAPI(reg.phoneNo, index); // Assuming 'phoneNo' is in each reg object
      });
    };
    fetchDataAndUpdate(); 
  }, []); // Empty dependency array runs once on component mount

  render() {
    const { registrations, isLoadingMNP } = this.state;
    return (
      // ... your JSX rendering logic ...
      //  Handle isLoadingMNP  to display loading indicators while fetching
    );
  }
}
