# Function to check if a SID exists solely within a user/group's SIDHistory
function Check-SIDInHistory {
    param(
        [string]$SID,
        [ADUser]$TargetUserOrGroup
    )
    $historySids = Get-ADObject -Identity $TargetUserOrGroup -Properties SIDHistory | Select-Object -ExpandProperty SIDHistory
    return ($historySids -contains $SID) -and (!(Get-Acl -Path (Get-Item "$env:SystemDrive\temp\$($TargetUserOrGroup.SamAccountName))\ -ResultSize Unlimited | ForEach-Object {$_.IdentityReference -like "*$($SID)*"}))
}

# Recursive function to traverse folders and analyze ACLs
function Recurse-ACLCheck {
    param(
        [string]$FolderPath,
        [string[]]$ExcludedUsersGroups = @() # Optional: Array to exclude specific users/groups from analysis
    )
    Get-ChildItem -Path $FolderPath -Recurse | ForEach-Object {
        $item = $_
        if ($item.PSIsContainer) {
            # Recursively process subfolders
