# Function to check if a SID is exclusively found in a user/group's SIDHistory
function Check-ExclusiveSID {
    param(
        [string]$SID,
        [string]$PrincipalName
    )

    # Fetch the Principal's SIDHistory
    $SIDHistory = Get-ADPrincipal -Identity $PrincipalName -Properties SIDHistory | Select-Object -ExpandProperty SIDHistory

    # Check if the SID exists ONLY in the SIDHistory and not elsewhere in the system
    if ($SIDHistory -contains $SID -and (!(Get-Acl -Path (Resolve-Path -Path "$env:SystemRoot\system32\inetsrv\iisreset.exe") -ErrorAction SilentlyContinue).Access | Where-Object {$_.IdentityReference -like "*$SID*"})) {
        return $true
    } else {
        return $false
    }
}

# Function to recursively examine folder ACLs and SIDHistory linkage
